from vlb_traj import Session
import numpy as np
p=np.array([-0.3636052746904022,-0.03980154475704273])
with Session() as s:
 st=s.state(); q0=np.array(st['robot']['joint_positions']); quat=np.array(st['robot']['tcp_quaternion_wxyz'])
 s.record_start()
 def target(z):
  r=s.ik([p[0],p[1],z],quat)
  if not r['success']: raise RuntimeError(f'IK failed at z={z}')
  return np.asarray(r['joint_positions'])
 def move(q1,n,fingers):
  qstart=np.array(s.state()['robot']['joint_positions'])
  for i in range(1,n+1):
   a=qstart+(q1-qstart)*(i/n)
   out=s.step(np.r_[a,fingers])
   print('step',out['sim_steps'],'success',out['success'],'tcp',np.round(s.state()['robot']['tcp_position'],3),flush=True)
   if out['success']: return True
  return False
 ok=move(target(.88),35,[.04,.04])
 if not ok:
  for j in range(8):
   out=s.step(np.r_[s.state()['robot']['joint_positions'],[0.0,0.0]])
   if out['success']: ok=True; break
 if not ok: ok=move(target(.79),20,[0.0,0.0])
 if not ok:
  for j in range(20):
   out=s.step(np.r_[s.state()['robot']['joint_positions'],[0.0,0.0]])
   print('hold',out['sim_steps'],'success',out['success'],flush=True)
   if out['success']: ok=True; break
 final=s.status(); print('FINAL',final,flush=True)
 actions=s.record_stop(); print('ACTIONS',actions.shape,flush=True)
 if final['success']:
  s.save_trajectory(actions,'/app/output/trajectory.npz'); print('SAVED',flush=True)
